 @org.junit.jupiter.api.Test void isolatedDatabaseContract()throws Exception{main(new String[0]);}
 static PGSimpleDataSource runtime,migrator;static DataSource tracked;static UUID tenant,actor=UUID.randomUUID();static int checks;static AtomicInteger open=new AtomicInteger(),verified=new AtomicInteger();static AtomicBoolean revoked=new AtomicBoolean(),loseCommit=new AtomicBoolean();static final Instant AT=Instant.parse("2026-10-21T00:00:00.123456789Z");
 static UUID id(){return UUID.randomUUID();}static Access access(){return new Access(tenant,actor,1);}static Scope scope(){return new Scope(tenant,id(),new Deduplication(id(),id(),Channel.WEBHOOK,id(),"OPENED"));}
 static void check(boolean value,String name){if(!value)throw new AssertionError(name);checks++;System.out.println("JOURNAL_PASS "+name);}
 interface Run{void run()throws Exception;}
 static void reject(Run run,int status,String name)throws Exception{try{run.run();throw new AssertionError("accepted "+name);}catch(DomainException e){check(e.status==status&&e.getCause()==null&&!e.getMessage().contains("SYNTHETIC_PRIVATE"),name);}}
 static void sqlReject(String sql,String name)throws Exception{try(var c=runtime.getConnection();var q=c.createStatement()){try{q.execute(sql);throw new AssertionError("accepted "+name);}catch(SQLException e){check(Set.of("23514","23505","23503","42501").contains(e.getSQLState()),name);}}}
 static PGSimpleDataSource ds(String user,String password){var d=new PGSimpleDataSource();d.setURL(System.getenv("SPRING_DATASOURCE_URL"));d.setUser(user);d.setPassword(password);return d;}
 static void authorize(Connection c,Access a,Scope s,Operation o)throws SQLException{if(c.getAutoCommit()||!a.tenantId().equals(tenant)||!a.actorId().equals(actor)||a.permissionVersion()!=1||revoked.get())throw new DomainException(403,"REVOKED","SYNTHETIC_PRIVATE");}
 static PostgresDeliveryReceiptRepository repo(){return new PostgresDeliveryReceiptRepository(tracked,DeliveryReceiptPostgresTest::authorize,(c,a,s,command)->{if(c.getAutoCommit())throw new AssertionError("outside transaction");verified.incrementAndGet();});}
 static Command cmd(long version,Transition t){return new Command(version,id(),actor,1,"synthetic-journal",t);}
 static long count(Scope s)throws Exception{try(var c=runtime.getConnection();var q=c.prepareStatement("SELECT count(*) FROM mop_delivery_receipt_journal WHERE tenant_id=? AND delivery_id=?")){q.setObject(1,tenant);q.setObject(2,s.deliveryId());try(var r=q.executeQuery()){r.next();return r.getLong(1);}}}
 static DataSource tracking(){return (DataSource)Proxy.newProxyInstance(DataSource.class.getClassLoader(),new Class[]{DataSource.class},(p,m,a)->{try{Object result=m.invoke(runtime,a);if(!(result instanceof Connection raw))return result;open.incrementAndGet();var closed=new AtomicBoolean();return Proxy.newProxyInstance(Connection.class.getClassLoader(),new Class[]{Connection.class},(proxy,method,args)->{try{Object answer=method.invoke(raw,args);if(method.getName().equals("commit")&&loseCommit.compareAndSet(true,false))throw new SQLException("SYNTHETIC_PRIVATE lost commit reply","08006");return answer;}catch(InvocationTargetException e){throw e.getCause();}finally{if(method.getName().equals("close")&&closed.compareAndSet(false,true))open.decrementAndGet();}});}catch(InvocationTargetException e){throw e.getCause();}});}
 public static void main(String[]args)throws Exception{
  if(!"dot-delivery-journal-disposable".equals(System.getenv("MOP_DELIVERY_JOURNAL_TEST_ENVIRONMENT")))throw new IllegalStateException("Explicit disposable gate required");
  runtime=ds("mop_test_runtime",System.getenv("SPRING_DATASOURCE_PASSWORD"));migrator=ds("mop_test_migrator",System.getenv("MOP_MIGRATION_PASSWORD"));tracked=tracking();try(var c=runtime.getConnection();var q=c.createStatement();var r=q.executeQuery("SELECT id FROM mop_tenant ORDER BY id LIMIT 1")){if(!r.next())throw new AssertionError("tenant missing");tenant=r.getObject(1,UUID.class);}
  var repository=repo();var s=scope();UUID queue=id(),request=id();check(repository.current(access(),s).isEmpty(),"authorized_missing_root_is_empty");var queued=repository.queue(access(),s,queue,AT,"queue");check(!queued.replay()&&queued.databaseRecorded()&&!queued.automaticSendEnabled()&&!queued.providerReceiptVerified()&&queued.journal().state().version()==0,"queued_root_is_recorded_not_dispatch_authority");check(repository.queue(access(),s,queue,AT,"queue").replay()&&count(s)==1,"exact_queue_replay_no_new_row");
  reject(()->repository.queue(access(),s,queue,AT.plusNanos(1),"queue"),409,"changed_queue_time_rejected");reject(()->repository.queue(access(),scope(),queue,AT,"queue"),409,"command_id_cannot_move_delivery");var duplicateKey=new Scope(tenant,id(),s.key());reject(()->repository.queue(access(),duplicateKey,id(),AT,"queue"),409,"dedup_tuple_cannot_create_second_delivery");
  var start=cmd(0,new Started(request,AT.plusNanos(1)));var started=repository.append(access(),s,start);check(started.journal().state().status()==Status.UNKNOWN&&count(s)==2,"persist_start_before_any_external_io");check(repository.append(access(),s,start).replay()&&count(s)==2,"same_start_replays_original_command");reject(()->repository.append(access(),s,cmd(1,new Started(id(),AT.plusSeconds(10)))),409,"unknown_does_not_become_retryable");
  var accepted=cmd(1,new ReceiptRecorded(new cn.mop.domain.notification.DeliveryReceiptState.Receipt(tenant,s.deliveryId(),request,id(),ReceiptStatus.ACCEPTED,AT.plusNanos(2)),AT.plusNanos(3)));repository.append(access(),s,accepted);
  var failed=cmd(2,new ReceiptRecorded(new cn.mop.domain.notification.DeliveryReceiptState.Receipt(tenant,s.deliveryId(),request,id(),ReceiptStatus.FAILED,AT.plusNanos(4)),AT.plusNanos(5)));repository.append(access(),s,failed);repository.append(access(),s,cmd(3,new DeadLettered(AT.plusNanos(6))));repository.append(access(),s,cmd(4,new Started(id(),AT.plusNanos(7))));var delivered=cmd(5,new ReceiptRecorded(new cn.mop.domain.notification.DeliveryReceiptState.Receipt(tenant,s.deliveryId(),request,id(),ReceiptStatus.DELIVERED,AT.plusNanos(2)),AT.plusNanos(8)));repository.append(access(),s,delivered);
  var restored=repo().current(access(),s).orElseThrow();check(restored.journal().state().status()==Status.DELIVERED&&restored.journal().state().logicalDeliveredCount()==1&&restored.journal().state().observedAt().equals(AT.plusNanos(8))&&count(s)==7,"new_repository_restores_full_nanos_and_late_old_delivery");var replay=repository.append(access(),s,start);check(replay.replay()&&replay.appliedVersion()==1&&replay.journal().state().status()==Status.DELIVERED,"original_start_replay_returns_current_delivered_state");check(repository.queue(access(),s,queue,AT,"queue").journal().state().status()==Status.DELIVERED,"queue_replay_returns_current_not_stale_queued");
  reject(()->repository.append(access(),s,new Command(0,start.commandId(),actor,1,"changed",start.transition())),409,"original_command_payload_cannot_change");reject(()->repository.append(access(),s,cmd(6,accepted.transition())),409,"new_command_duplicate_receipt_no_phantom_version");reject(()->repository.current(access(),new Scope(tenant,s.deliveryId(),scope().key())),404,"wrong_full_dedup_scope_not_found");revoked.set(true);reject(()->repository.append(access(),s,start),403,"replay_reauthorizes_current_access");revoked.set(false);
  var deniedScope=scope();var denyAfterInsert=new AtomicInteger();var finalVeto=new PostgresDeliveryReceiptRepository(tracked,(c,a,k,o)->{authorize(c,a,k,o);if(denyAfterInsert.incrementAndGet()==2)throw new DomainException(403,"REVOKED","SYNTHETIC_PRIVATE");},(c,a,k,command)->{});reject(()->finalVeto.queue(access(),deniedScope,id(),AT,"queue"),403,"final_authorization_veto_rolls_back_root");check(count(deniedScope)==0,"veto_leaves_no_root");
  var pending=scope();repository.queue(access(),pending,id(),AT,"queue");var pendingStart=cmd(0,new Started(id(),AT));var deniedProof=new PostgresDeliveryReceiptRepository(tracked,DeliveryReceiptPostgresTest::authorize,(c,a,k,command)->{throw new IllegalStateException("SYNTHETIC_PRIVATE");});reject(()->deniedProof.append(access(),pending,pendingStart),503,"missing_trusted_prerequisite_fails_closed");check(count(pending)==1,"failed_prerequisite_leaves_no_event");
  loseCommit.set(true);reject(()->repository.append(access(),pending,pendingStart),503,"lost_commit_response_is_not_reported_success");check(repository.append(access(),pending,pendingStart).replay()&&count(pending)==2,"lost_commit_recovery_reuses_original_event");
  var race=scope();repository.queue(access(),race,id(),AT,"queue");var pool=Executors.newFixedThreadPool(2);try{var latch=new CountDownLatch(1);var futures=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++)futures.add(pool.submit(()->{latch.await();try{repo().append(access(),race,cmd(0,new Started(id(),AT)));return true;}catch(DomainException e){if(e.status!=409)throw e;return false;}}));latch.countDown();int wins=0;for(var f:futures)if(f.get(15,TimeUnit.SECONDS))wins++;check(wins==1&&count(race)==2,"distinct_concurrent_commands_one_winner");}finally{pool.shutdownNow();}
  var same=scope();repository.queue(access(),same,id(),AT,"queue");var sameCommand=cmd(0,new Started(id(),AT));var samePool=Executors.newFixedThreadPool(2);try{var latch=new CountDownLatch(1);var futures=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++)futures.add(samePool.submit(()->{latch.await();return repo().append(access(),same,sameCommand).replay();}));latch.countDown();int replays=0;for(var f:futures)if(f.get(15,TimeUnit.SECONDS))replays++;check(replays==1&&count(same)==2,"identical_concurrent_command_one_append_one_replay");}finally{samePool.shutdownNow();}
  reject(()->deniedProof.append(access(),s,start),503,"original_replay_still_requires_trusted_prerequisite");
  var vetoEvent=scope();repository.queue(access(),vetoEvent,id(),AT,"queue");var authCalls=new AtomicInteger();var eventVeto=new PostgresDeliveryReceiptRepository(tracked,(c,a,k,o)->{authorize(c,a,k,o);if(authCalls.incrementAndGet()==2)throw new DomainException(403,"REVOKED","SYNTHETIC_PRIVATE");},(c,a,k,command)->{});reject(()->eventVeto.append(access(),vetoEvent,cmd(0,new Started(id(),AT))),403,"final_append_authorization_veto_rolls_back_event");check(count(vetoEvent)==1&&repository.current(access(),vetoEvent).orElseThrow().journal().state().version()==0,"append_veto_keeps_original_queued_root");
  var queueRace=scope();UUID queueRaceCommand=id();var queuePool=Executors.newFixedThreadPool(2);try{var latch=new CountDownLatch(1);var futures=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++)futures.add(queuePool.submit(()->{latch.await();try{return repo().queue(access(),queueRace,queueRaceCommand,AT,"queue").replay()?2:1;}catch(DomainException e){if(e.status!=409)throw e;return 0;}}));latch.countDown();int created=0;for(var f:futures)if(f.get(15,TimeUnit.SECONDS)==1)created++;check(created==1&&count(queueRace)==1,"concurrent_identical_queue_has_one_root");check(repository.queue(access(),queueRace,queueRaceCommand,AT,"queue").replay(),"queue_conflict_can_recover_exact_original");}finally{queuePool.shutdownNow();}
  String fields="tenant_id,delivery_id,version,resource_pool_id,event_id,channel,receiver_id,stage,command_id,actor_id,permission_version,trace_id,expected_version,previous_sha256,encoded_record,record_sha256,command_sha256";
  String source=" FROM mop_delivery_receipt_journal WHERE tenant_id='"+tenant+"' AND delivery_id='"+vetoEvent.deliveryId()+"' AND version=0";
  sqlReject("INSERT INTO mop_delivery_receipt_journal ("+fields+") SELECT tenant_id,delivery_id,2,resource_pool_id,event_id,channel,receiver_id,stage,'"+id()+"',actor_id,permission_version,trace_id,1,record_sha256,encoded_record,record_sha256,command_sha256"+source,"direct_sql_skipped_version_rejected");
  sqlReject("INSERT INTO mop_delivery_receipt_journal ("+fields+") SELECT tenant_id,delivery_id,1,resource_pool_id,event_id,channel,receiver_id,stage,'"+id()+"',actor_id,permission_version,trace_id,0,repeat('0',64),encoded_record,record_sha256,command_sha256"+source,"direct_sql_wrong_predecessor_rejected");
  sqlReject("INSERT INTO mop_delivery_receipt_journal ("+fields+") SELECT tenant_id,delivery_id,1,resource_pool_id,event_id,channel,'"+id()+"',stage,'"+id()+"',actor_id,permission_version,trace_id,0,record_sha256,encoded_record,record_sha256,command_sha256"+source,"direct_sql_cross_receiver_scope_rejected");
  sqlReject("UPDATE mop_delivery_receipt_journal SET root_version=0 WHERE delivery_id='"+s.deliveryId()+"'","runtime_lock_column_cannot_be_updated");sqlReject("DELETE FROM mop_delivery_receipt_journal WHERE delivery_id='"+s.deliveryId()+"'","runtime_delete_denied");sqlReject("TRUNCATE mop_delivery_receipt_journal","runtime_truncate_denied");sqlReject("UPDATE mop_delivery_receipt_journal SET record_sha256=repeat('0',64)","runtime_other_column_update_denied");
  byte[] original;try(var c=migrator.getConnection();var q=c.prepareStatement("SELECT encoded_record FROM mop_delivery_receipt_journal WHERE tenant_id=? AND delivery_id=? AND version=1")){q.setObject(1,tenant);q.setObject(2,s.deliveryId());try(var r=q.executeQuery()){r.next();original=r.getBytes(1);}}var corrupt=original.clone();corrupt[0]^=1;tamper(s,corrupt);try{reject(()->repository.current(access(),s),503,"corrupt_original_event_never_returned_as_valid");}finally{tamper(s,original);}check(repository.current(access(),s).orElseThrow().journal().state().status()==Status.DELIVERED,"restored_original_bytes_read_again");check(verified.get()>0&&open.get()==0,"prerequisites_invoked_and_all_connections_closed");System.out.println("TOTAL_JOURNAL_PASS="+checks);
 }
 static void tamper(Scope s,byte[] bytes)throws Exception{try(var c=migrator.getConnection()){c.setAutoCommit(false);try(var q=c.createStatement()){q.execute("ALTER TABLE mop_delivery_receipt_journal DISABLE TRIGGER mop_delivery_receipt_journal_guard");}try(var q=c.prepareStatement("UPDATE mop_delivery_receipt_journal SET encoded_record=? WHERE tenant_id=? AND delivery_id=? AND version=1")){q.setBytes(1,bytes);q.setObject(2,tenant);q.setObject(3,s.deliveryId());q.executeUpdate();}try(var q=c.createStatement()){q.execute("ALTER TABLE mop_delivery_receipt_journal ENABLE TRIGGER mop_delivery_receipt_journal_guard");}c.commit();}}
